import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ConfigService {
    private static final String BASE_DIR = "/opt/configs";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config", new ConfigHandler());
        server.createContext("/api/config/history", new HistoryHandler());
        server.setExecutor(null);
        server.start();
    }

    static class ConfigHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"GET".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }

            Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
            String tenant = params.getOrDefault("tenant", "default");
            String filename = params.getOrDefault("file", "application.yml");

            // Validate tenant is alphanumeric
            if (!tenant.matches("[a-zA-Z0-9_-]+")) {
                sendResponse(exchange, 400, "{\"error\":\"invalid tenant\"}");
                return;
            }

            // Build path - filename is user-controlled
            String filePath = BASE_DIR + "/" + tenant + "/" + filename;

            try {
                byte[] content = Files.readAllBytes(Paths.get(filePath));
                exchange.getResponseHeaders().set("Content-Type", "application/octet-stream");
                exchange.sendResponseHeaders(200, content.length);
                exchange.getResponseBody().write(content);
                exchange.getResponseBody().close();
            } catch (NoSuchFileException e) {
                sendResponse(exchange, 404, "{\"error\":\"not found\"}");
            } catch (IOException e) {
                sendResponse(exchange, 500, "{\"error\":\"read error\"}");
            }
        }
    }

    static class HistoryHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"GET".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }

            Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
            String tenant = params.getOrDefault("tenant", "default");
            String version = params.getOrDefault("version", "latest");
            String file = params.getOrDefault("file", "application.yml");

            // Version must be numeric or 'latest'
            if (!"latest".equals(version) && !version.matches("[0-9]+")) {
                sendResponse(exchange, 400, "{\"error\":\"invalid version\"}");
                return;
            }

            // No validation on file parameter for history lookups
            String histPath = BASE_DIR + "/history/" + tenant + "/" + version + "/" + file;

            try {
                byte[] content = Files.readAllBytes(Paths.get(histPath));
                exchange.getResponseHeaders().set("Content-Type", "application/octet-stream");
                exchange.sendResponseHeaders(200, content.length);
                exchange.getResponseBody().write(content);
                exchange.getResponseBody().close();
            } catch (NoSuchFileException e) {
                sendResponse(exchange, 404, "{\"error\":\"not found\"}");
            } catch (IOException e) {
                sendResponse(exchange, 500, "{\"error\":\"read error\"}");
            }
        }
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> params = new HashMap<>();
        if (query == null) return params;
        for (String pair : query.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                params.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                           URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return params;
    }

    static void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        byte[] bytes = body.getBytes();
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(code, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.getResponseBody().close();
    }
}
